const purposeFields=['admitted_at','company_id','expires_at','ordinary_until','policy_id','receipt','receipt_hash','reviewer_user_id','version']
function signedPurpose(p:Record<string,unknown>,signer=issuer,signingKey=key){const bytes=Buffer.from(JSON.stringify(p));return{issuerId:signer,payloadBase64:bytes.toString('base64'),signatureHex:createHmac('sha256',signingKey).update(bytes).digest('hex')}}
async function purposeEnvelope(change:(p:Record<string,unknown>)=>void=()=>{}){
 const g=(await db.query<{v:{familyCommitment:string;fields:string[];minimum:string}}>('SELECT gridex_ediel_retention.completed_parent_purpose_scope_v1($1,$2) v',[c,source])).rows[0].v
 const D=new Date(Date.now()+60000).toISOString(),E=new Date(Date.now()+120000).toISOString(),p:Record<string,unknown>={format:'ediel_completed_source_parent_purpose_policy_v1',purpose:'ordinary_retention_evidence_use',scope:'ordinary_metadata_and_original_disclosure',holdTreatment:'preserve_under_hold_without_post_D_ordinary_disclosure',companyId:c,policyId:source,version:1,predecessorHash:null,familyCommitment:g.familyCommitment,issuerLegalReference:'SYNTHETIC issuer competence',issuedAt:new Date(Date.now()-1000).toISOString(),expiresAt:new Date(Date.now()+3600000).toISOString(),D,E,reviewerId:reviewer,fields:g.fields.map(field=>({field,purposeReference:'SYNTHETIC independently qualified ordinary-use end',basisReference:'SYNTHETIC bounded competence GIVEN; no Gridex legal assertion',min:new Date(Date.parse(g.minimum)-60000).toISOString(),max:D,ordinaryUseEnds:D,reviewBy:E,action:'erase_with_qualified_current_approval'})),policyFields:purposeFields.map(field=>({field:'purpose.'+field,purposeReference:'SYNTHETIC finite necessary current purpose authority',basisReference:'SYNTHETIC separately qualified control storage GIVEN',min:new Date(Date.now()-60000).toISOString(),max:E,reviewBy:E,action:'erase_with_source_or_qualified_successor_by_E'}))};change(p);return signedPurpose(p)
}
function setPurposeTimes(p:Record<string,unknown>,D:string,E:string){p.D=D;p.E=E;for(const f of p.fields as {max:string;ordinaryUseEnds:string;reviewBy:string}[]){f.max=D;f.ordinaryUseEnds=D;f.reviewBy=E}for(const f of p.policyFields as {max:string;reviewBy:string}[]){f.max=E;f.reviewBy=E}}
async function admitPurpose(e:unknown){await actor(reviewer);return(await db.query<{v:unknown}>('SELECT public.ediel_admit_completed_parent_purpose_v1($1,$2,$3,$4) v',[c,reviewer,source,JSON.stringify(e)])).rows[0].v}
async function currentPurpose(){return(await db.query<{v:{version:number;receiptHash:string;D:string;E:string;payload:Record<string,unknown>}|null}>('SELECT gridex_ediel_retention.completed_parent_purpose_current_v1($1,$2) v',[c,source])).rows[0].v}
async function purposeApproval(short=false,change:(p:Record<string,unknown>)=>void=()=>{}){const P=(await currentPurpose())!;return parentEnvelope(p=>{p.purposeVersion=String(P.version);p.purposeHash=P.receiptHash;p.W=P.D;p.R=P.D;for(const f of p.fields as {max:string}[])f.max=P.D;change(p)},short)}
async function allPortsReadable(id=source){await actor();for(const include of [false,true]){
 const generic=(await db.query<{v:{policyId:string;documentBase64:string|null;reviews:unknown[]}}>('SELECT public.ediel_read_decision_evidence_policy_v1($1,$2,$3,$4) v',[c,worker,id,include])).rows[0].v;expect(generic.policyId).toBe(id);if(include)expect(Buffer.from(generic.documentBase64!,'base64').toString()).toBe('SYNTHETIC parent policy original');else expect(generic.documentBase64).toBeNull()
 const alternate=(await db.query<{v:{bytesAvailable:boolean;documentBase64:string|null}}>("SELECT public.ediel_read_retention_decision_original_v1($1,$2,'decision_evidence_policy_original_bytes',$3,$4) v",[c,worker,id,include])).rows[0].v;expect(alternate.bytesAvailable).toBe(true);if(include)expect(Buffer.from(alternate.documentBase64!,'base64').toString()).toBe('SYNTHETIC parent policy original');else expect(alternate.documentBase64).toBeNull()
}}
